// Generated from the original argparse parser AST; no business import.
use quantnight_task_core::cli_args::{parse_args, CliParse, CliValue, CLI_HELP_EXIT_CODE};
use serde_json::{json, Value};
fn value(v: &CliValue) -> Value {
    match v {
        CliValue::Null => json!({"kind":"null"}),
        CliValue::Bool(v) => json!({"kind":"bool","value":v}),
        CliValue::String(v) => json!({"kind":"string","value":v}),
        CliValue::Integer(v) => json!({"kind":"integer","value":v}),
        CliValue::Float(v) => json!({"kind":"float","bits":format!("{:016x}",v.to_bits())}),
    }
}
#[test]
fn original_argparse_matches_registered_rust_parser() {
    let cases: Vec<Value> = serde_json::from_str(GOLDEN).unwrap();
    for case in cases {
        let args: Vec<String> = serde_json::from_value(case["args"].clone()).unwrap();
        let actual = match parse_args(&args) {
            Ok(CliParse::Help { command }) => {
                json!({"kind":"help","exit":CLI_HELP_EXIT_CODE,"command":command})
            }
            Ok(CliParse::Command(invocation)) => {
                let options: serde_json::Map<String, Value> = invocation
                    .options
                    .iter()
                    .map(|(k, v)| (k.clone(), value(v)))
                    .collect();
                json!({"kind":"command","command":invocation.command,"name":invocation.name,"options":options})
            }
            Err(error) => {
                assert!(!error.message.is_empty());
                json!({"kind":"error","exit":error.exit_code})
            }
        };
        let mut expected = case["expected"].clone();
        // Error formatting/prog/usage wrapping differs across argparse versions;
        // compare usage exit semantics, while preserving original text in fixtures.
        if expected["kind"] == "error" {
            expected.as_object_mut().unwrap().remove("message");
            expected.as_object_mut().unwrap().remove("errorCommand");
        }
        assert_eq!(actual, expected, "{} argv={:?}", case["label"], args);
    }
}
